 <thead>
  <tr>
   <th style="text-align:left;"> Supuesto </th>
   <th style="text-align:left;"> Qué pasa si falla </th>
   <th style="text-align:left;"> Cómo se revisa </th>
  </tr>
 </thead>
<tbody>
  <tr>
   <td style="text-align:left;"> Linealidad </td>
