```{.r .cell-code}
# 3) Box-Cox a mano: perfil de verosimilitud con la versión normalizada
y <- cuencas$caudal_m3s
n <- length(y)
y_geo <- exp(mean(log(y)))                  # media geométrica
perfil <- function(lambda) {
  z <- if (abs(lambda) < 1e-8) y_geo * log(y) else (y^lambda - 1) / (lambda * y_geo^(lambda - 1))
  sse <- sum(residuals(lm(z ~ cuencas$area_km2))^2)
  -n / 2 * log(sse / n)
}
lambdas <- seq(-1, 1.5, by = 0.01)
l_perfil <- sapply(lambdas, perfil)
lambda_hat <- lambdas[which.max(l_perfil)]
ic_lambda <- range(lambdas[l_perfil >= max(l_perfil) - qchisq(0.95, df = 1) / 2])
c(lambda = lambda_hat, inferior = ic_lambda[1], superior = ic_lambda[2])
