y <- proctor$densidad
n <- length(y)
b1 <- sum(z * y) / sum(z^2)
A <- rbind(c(n, sum(z^2)), c(sum(z^2), sum(z^4)))
b02 <- solve(A, c(sum(y), sum(z^2 * y)))
c(b0 = b02[1], b1 = b1, b2 = b02[2])
```

